-- =====================================================================================================================
-- 4. DEMO ACTIVITY
-- =====================================================================================================================
-- ---------------------------------------------------------------------------------------------------------------------
-- Demo activity (leads, bookings, tasks, chats, garage cars, AI call log, call log). Every id starts with 5eed, so this
-- function can remove and re-create exactly its own rows and nothing else. All dates are offsets from the moment it
-- runs. Run it again right before a demo to make the screens fresh:  select private.refresh_demo_activity();
-- ---------------------------------------------------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION private.refresh_demo_activity()
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $demo$
BEGIN
  -- Remove the previous demo rows, children first.
  DELETE FROM public.call_logs WHERE id::text LIKE '5eed%';
  DELETE FROM public.ai_logs WHERE id::text LIKE '5eed%';
  DELETE FROM public.lead_tasks WHERE id::text LIKE '5eed%';
  DELETE FROM public.chat_messages WHERE id::text LIKE '5eed%';
  DELETE FROM public.chat_conversations WHERE id::text LIKE '5eed%';
  DELETE FROM public.trade_in_requests WHERE id::text LIKE '5eed%';
  DELETE FROM public.saved_items WHERE id::text LIKE '5eed%';
  DELETE FROM public.service_records WHERE id::text LIKE '5eed%';
  DELETE FROM public.owner_vehicles WHERE id::text LIKE '5eed%';
  DELETE FROM public.consents WHERE id::text LIKE '5eed%';
  DELETE FROM public.bookings WHERE id::text LIKE '5eed%';
  DELETE FROM public.lead_events WHERE id::text LIKE '5eed%';
  DELETE FROM public.leads WHERE id::text LIKE '5eed%';
  DELETE FROM public.slots WHERE id::text LIKE '5eed%';
  DELETE FROM public.used_car_sales_history WHERE id::text LIKE '5eed%';

  -- Insert them again, parents first.
