    ('5eed0070-0000-0000-0000-000000000002', NULL, '5eed0070-0000-0000-0000-00000000000a', 'Can I book a drive for Saturday?', 'waiting', '5eed0010-0000-0000-0000-000000000009', '00000000-0000-0000-0000-000000000010', '{"summary":"Priya asked for the on-road price and EMI of a petrol sedan, then wanted a Saturday test drive and asked for a consultant.","intents":["price","emi","test_drive"],"buyerQuestions":["what is the on road price for the Model H?","EMI for 5 years?","can I book a drive for Saturday?"],"lastQuestion":"can I book a drive for Saturday?","suggestedReply":"Hi Priya, this is your Vrooma consultant. I can book your Saturday test drive right now. Which time suits you?","buyerName":"Priya Nair","signedIn":false,"messageCount":7,"builtAt":"2026-11-09T09:48:00.000Z"}'::jsonb, (pg_catalog.now() + interval '-720 seconds'), NULL, NULL, NULL, (pg_catalog.now() + interval '-1200 seconds'), (pg_catalog.now() + interval '-720 seconds')),
    ('5eed0070-0000-0000-0000-000000000003', '00000000-0000-0000-0000-000000000001', NULL, 'Question about my test drive', 'live', '5eed0010-0000-0000-0000-00000000000c', '00000000-0000-0000-0000-000000000010', '{"summary":"Aditya asked whether he needs documents for his Model H test drive.","intents":["test_drive"],"buyerQuestions":["do I need to carry my licence for the test drive?"],"lastQuestion":"do I need to carry my licence for the test drive?","suggestedReply":"Hi Aditya, yes please bring your driving licence. I will meet you at the entrance.","buyerName":"Aditya Mishra","signedIn":true,"messageCount":4,"builtAt":"2026-11-09T08:00:00.000Z"}'::jsonb, (pg_catalog.now() + interval '-7200 seconds'), (pg_catalog.now() + interval '-6600 seconds'), NULL, NULL, (pg_catalog.now() + interval '-7800 seconds'), (pg_catalog.now() + interval '-5700 seconds'))
