  INSERT INTO public.chat_messages (id, conversation_id, role, content, sender_id, created_at) VALUES
    ('5eed0071-0000-0000-0000-000000000001', '5eed0070-0000-0000-0000-000000000001', 'user', 'What would the EMI be on the Model H ZX for 5 years?', NULL, (pg_catalog.now() + interval '-173100 seconds')),
    ('5eed0071-0000-0000-0000-000000000002', '5eed0070-0000-0000-0000-000000000001', 'assistant', 'At the assumed rate of 9.5%, a ₹10,00,000 loan over 60 months comes to about ₹20,998 a month. The full schedule is at /emi-calculator.
  
  Is your query solved, or would you like to connect with a Vrooma consultant?', NULL, (pg_catalog.now() + interval '-173040 seconds')),
    ('5eed0071-0000-0000-0000-000000000003', '5eed0070-0000-0000-0000-000000000001', 'user', 'Yes, it''s solved', NULL, (pg_catalog.now() + interval '-173100 seconds')),
    ('5eed0071-0000-0000-0000-000000000004', '5eed0070-0000-0000-0000-000000000001', 'assistant', 'Glad I could help. Thank you for chatting with Vrooma. You can start a new chat any time.', NULL, (pg_catalog.now() + interval '-173040 seconds')),
    ('5eed0071-0000-0000-0000-000000000005', '5eed0070-0000-0000-0000-000000000002', 'user', 'what is the on road price for the Model H?', NULL, (pg_catalog.now() + interval '-1200 seconds')),
    ('5eed0071-0000-0000-0000-000000000006', '5eed0070-0000-0000-0000-000000000002', 'assistant', 'Every model page shows the ex-showroom price, and once you sign in you can see the full on-road breakup for your city, with a validity date. See /cars/model-h.
  
  Is your query solved, or would you like to connect with a Vrooma consultant?', NULL, (pg_catalog.now() + interval '-1140 seconds')),
    ('5eed0071-0000-0000-0000-000000000007', '5eed0070-0000-0000-0000-000000000002', 'user', 'EMI for 5 years?', NULL, (pg_catalog.now() + interval '-1020 seconds')),
    ('5eed0071-0000-0000-0000-000000000008', '5eed0070-0000-0000-0000-000000000002', 'assistant', 'Use the EMI calculator at /emi-calculator to set the loan amount, tenure and rate.
  
  Is your query solved, or would you like to connect with a Vrooma consultant?', NULL, (pg_catalog.now() + interval '-960 seconds')),
    ('5eed0071-0000-0000-0000-000000000009', '5eed0070-0000-0000-0000-000000000002', 'user', 'can I book a drive for Saturday?', NULL, (pg_catalog.now() + interval '-840 seconds')),
    ('5eed0071-0000-0000-0000-00000000000a', '5eed0070-0000-0000-0000-000000000002', 'user', 'Connect me to a consultant', NULL, (pg_catalog.now() + interval '-725 seconds')),
    ('5eed0071-0000-0000-0000-00000000000b', '5eed0070-0000-0000-0000-000000000002', 'system', 'A consultant will reply here shortly.', NULL, (pg_catalog.now() + interval '-720 seconds')),
    ('5eed0071-0000-0000-0000-00000000000c', '5eed0070-0000-0000-0000-000000000003', 'user', 'do I need to carry my licence for the test drive?', NULL, (pg_catalog.now() + interval '-7800 seconds')),
    ('5eed0071-0000-0000-0000-00000000000d', '5eed0070-0000-0000-0000-000000000003', 'system', 'You are connected with Dev Consultant. They will reply here shortly.', NULL, (pg_catalog.now() + interval '-7200 seconds')),
    ('5eed0071-0000-0000-0000-00000000000e', '5eed0070-0000-0000-0000-000000000003', 'consultant', 'Hi Aditya, yes please bring your driving licence. I will meet you at the showroom entrance.', '00000000-0000-0000-0000-000000000010', (pg_catalog.now() + interval '-6600 seconds')),
    ('5eed0071-0000-0000-0000-00000000000f', '5eed0070-0000-0000-0000-000000000003', 'user', 'Great, see you then.', NULL, (pg_catalog.now() + interval '-5700 seconds'))
  ON CONFLICT (id) DO NOTHING;

